/* Send every external link to one shared tab.
 *
 * The markdown render hook (layouts/_default/_markup/render-link.html) handles
 * links written in content. Links generated by theme templates, such as the
 * publication buttons, DOI links and author social icons, hardcode
 * target="_blank" and open a new tab each time. This normalises those to the
 * same named target, so the whole site behaves consistently: the first external
 * link opens a tab, and later ones reuse it.
 *
 * Runs after the theme's own scripts. Same-origin links are left alone.
 */
(function () {
  function normalise(root) {
    var host = window.location.hostname;
    var links = (root || document).querySelectorAll('a[href^="http://"], a[href^="https://"]');
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      if (a.hostname === host) continue;            // internal, leave it
      if (a.hasAttribute('download')) continue;     // downloads, leave it
      a.setAttribute('target', 'hxi-external');
      var rel = a.getAttribute('rel') || '';
      if (rel.indexOf('noopener') === -1) {
        a.setAttribute('rel', (rel + ' noopener').trim());
      }
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { normalise(); });
  } else {
    normalise();
  }
})();
